"""Main-authored concept prompts. Run one group only after the prior commit."""
from pathlib import Path
import json
import sys

ROOT=Path(__file__).resolve().parents[2]
state=json.loads((ROOT/'Blender/SET_BATCH_STATE.json').read_text(encoding='utf-8'))
number=int(sys.argv[1])
assert number in (2,3)
assert (ROOT/f'Blender/BatchTools/scratch/batch{number-1}_commit.json').is_file()
palettes={
    'Set06':'muted pine green, warm cream, rubber charcoal, restrained terracotta accents',
    'Set07':'muted brick red, warm ivory, dark graphite, restrained brass-yellow functional accents',
    'Set08':'muted steel blue, warm pale gray, dark graphite, restrained copper-orange accents',
    'Set09':'muted mustard yellow, warm off-white, graphite mechanisms, restrained slate-blue accents',
    'Set10':'muted sea green, warm limestone white, dark graphite, restrained amber functional accents',
    'Set11':'muted warm terracotta, warm ivory, graphite mechanisms, restrained olive-green accents',
}
subjects={
    'tree_transplanter':'An articulated four-wheel tree-transplanting utility vehicle. Compact rounded rear cab and engine counterweight, a visible waist steering joint, and a stout front circular root-ball cradle with four blunt curved digging petals held partly open. Empty cradle, no actual tree or soil. Hydraulic cylinders, robust tires, safe folded tool tips and a low stable stance. Readable forestry machine rather than a generic excavator.',
    'nursery_carrier_robot':'A low autonomous nursery tray carrier: six small sturdy wheels, a rounded rectangular battery chassis, two clearly stacked open tray racks containing a few simple plant pots and upright young saplings, compact functional navigation sensor bar and an accessible rear battery panel. Tool-like utility robot, no eyes or face; practical clearance between the racks and a gentle friendly silhouette.',
    'arched_nursery_greenhouse':'A compact single-span nursery greenhouse building with a rounded barrel-vault roof, thick arched ribs, muted translucent glazing, a broad sliding entry, small low masonry base, side ventilation flaps and visible simple planting benches inside. Keep greenhouse architecture clear and buildable, no landscape or separate props. A few restrained nursery trays may be inside.',
    'forest_watchtower':'A short sturdy circular forest fire lookout tower. Four broad slightly splayed legs supporting a rounded glazed observation cabin, a shallow conical cap with a blunt top, a wraparound balcony with thick safe railing and a readable external stair or ladder with platforms. Calm functional architecture, not fantasy; no trees or terrain, only individual structural footings.',
    'rail_inspection_trolley':'A short self-propelled rail inspection trolley with four visible flanged steel wheels on two axles, an open-sided rounded protective cab, a small hood, front sensor crossbar and compact rear toolbox. Railway wheel arrangement must be unmistakable. No road tires, tracks under the trolley, driver or scenery. Sturdy rounded panels and visible safe steps.',
    'side_loading_freight_shuttle':'A compact industrial side-loading freight shuttle on six rubber wheels. Offset rounded operator cabin at one end, low long chassis, recessed lateral load bay, a chunky retractable sideways lifting mast with two blunt forks and one simple secured cargo container. Clear side loading function, safe rounded corners, modest functional hydraulics; not a conventional front forklift.',
    'barrel_roof_freight_station':'A small rail freight station with a broad barrel roof spanning a raised loading platform, a compact brick-and-metal side office, wide open cargo door and shallow canopy on stout columns. Show actual loading edge and a short sturdy access ramp. A few attached bumpers, vents and fixtures; no train, rails extending away or landscape diorama.',
    'mechanical_signal_house':'A compact two-storey railway signal house with rounded masonry corners, a glazed upper operator room, shallow curved roof, external stout stairway and an attached visible mechanical linkage cabinet at ground level. One simple short semaphore mechanism beside the wall, with a broad blunt horizontal paddle. Restrained readable railway architecture, no track scenery or text.',
    'articulated_welding_mech':'A compact industrial welding robot on a stable four-foot base. A single stout three-jointed arm rises from a circular waist, ending in a blunt practical welding head with a small protective shroud. Visible flexible cable loops, broad rounded joint housings, service panels and a compact controller integrated in the base. No face, weapon, flame, sparks or separate workpiece.',
    'cylindrical_mixer':'A stationary compact materials mixer with a large tilted cylindrical drum mounted between two rounded support cheeks, broad circular front loading opening, visible drive ring and short motor housing. A small feed funnel and empty discharge chute make its function obvious. Thick stable feet and an integrated little operator panel; no vehicle cab or surrounding factory scenery.',
    'rounded_foundry_workshop':'A compact foundry workshop with a softly curved sawtooth-like single raised roof vent, thick softened masonry walls, one tall open service bay, a rounded exterior exhaust duct connected to a short stack, a small side office and shallow foundation. Inside the bay show only a simple protected furnace housing. No exposed molten metal, flames, people or surrounding factory.',
    'vertical_material_tower':'A compact vertical bulk-material storage facility. Two tall rounded cylindrical bins on a stout four-column frame, conical lower hoppers with blunt short outlets above a clearly empty loading gap, an attached vertical elevator duct with a curved head, service ladder and a small top walkway. Functional industrial tower, soft-edged structure, no landscape or detached cargo vehicle.',
    'tracked_snowplow':'A compact tracked snow clearing vehicle with two broad low continuous tracks, rounded enclosed heated cab, short engine housing and a wide shallow curved plow blade whose corners are rounded. Visible blade lift arms and cylinders, small rear winch and functional light bar. Dry neutral studio, no snow terrain, people or decorative spikes.',
    'freight_cable_car':'An industrial aerial freight cable car shown as a complete isolated assembly. Small rounded rectangular cargo cabin with a large simple loading door, sturdy lower frame, one overhead suspension arm and two clearly visible pulley bogies at the top. Include a minimal short cable segment only through the pulleys. No ski passengers or landscape; clear cargo proportions and safe thick hardware.',
    'cable_drive_station':'A compact cableway drive station with a rounded barrel canopy over a visibly large horizontal return bullwheel, stout central shaft, paired support columns, two short guide cable segments and a small attached enclosed motor room. Empty service area with low railing and shallow foundation. Clear practical cable routing, no mountains or suspended cabins.',
    'modular_mountain_shelter':'A compact alpine utility shelter composed of two rounded rectangular modules joined by a short vestibule. Gently arched insulated roofs, small deep-set windows, a sturdy sheltered entrance and broad short steps, compact roof exhaust and an attached storage box. Restrained functional remote architecture, no snow, rocks or landscape base.',
    'turbine_service_crawler':'A low tracked wind-turbine maintenance machine with two broad short tracks, rounded equipment body, a compact folded articulated service boom with a blunt gripper saddle, visible hydraulic joints and integrated tool compartments. A small functional sensor mast, no person cabin required. No turbine or surrounding landscape; recognizable compact maintenance equipment, no face.',
    'generator_transport_trailer':'A compact four-wheel generator transport trailer with a single rounded rectangular generator enclosure, deep inset ventilation grilles, short folded exhaust, stout drawbar with visible towing eye, two axles, small support leg and rounded fenders. No towing truck, cable clutter or scenery. Practical proportions, quiet mature-friendly industrial game art.',
    'tidal_power_module':'A self-contained small tidal power module: a thick rounded protective circular duct enclosing one visible broad-bladed water turbine, mounted between two sturdy support legs on narrow individual footings, with a compact attached generator pod and curved cable conduit. Entire assembly visible dry in studio, no water, seabed, fish or landscape. Soft functional edges and coherent turbine axis.',
    'circular_power_control_house':'A low circular power control house with a softened segmented dome roof, curved wall panels, a broad practical entrance, small horizontal windows and an attached rounded electrical switchgear annex. A visible short heavy conduit links annex and main building; roof vents and shallow foundation. No wind turbines, landscape or decorative sci-fi antenna forest.',
    'mobile_grain_mill':'A compact mobile grain milling machine on a four-wheel utility chassis. A small rounded cab at front, one upright cylindrical milling housing behind it, a broad top grain hopper with softened rim and a short folded discharge auger. Visible belt guard, motor and service step. Grain processing must be legible; no grain pile, farmland or people.',
    'refrigerated_delivery_robot':'A low autonomous cold-chain delivery robot with six small rubber wheels and a broad rounded insulated cargo box. Two rear access doors with thick seals, top front compact refrigeration grille, a simple functional sensor bar, sturdy bumper and small lifting handles. Utilitarian, no eyes, face or toy motifs. Clearly different from a humanoid robot.',
    'curved_roof_flour_mill':'A compact flour mill building with a broad curved metal roof, softened masonry base, one clearly attached round grain silo, an exterior enclosed elevator duct rising to the silo head, wide loading door, modest upper windows and a short feed pipe into the mill. Practical coherent grain flow, restrained game architecture, no landscape or vehicles.',
    'modular_cold_store':'A compact modular refrigerated storage building made from two rounded-corner insulated rectangular volumes. One broad sealed loading door with a thick rubber dock surround, shallow loading platform and short ramp, attached twin-fan condenser unit with protected fan grilles, roof service vent and small staff door. No labels, ice motifs, truck or surrounding industrial scenery.',
}
common=('Use case: stylized-concept.\n'
    'Asset type: one original design reference image for one editable rounded 3D game model (ordinary smooth/beveled mesh, NOT voxels).\n'
    'Style: calm, mature-friendly game art. Rounded silhouettes and corners; retain recognizable functional structure. Broad simple forms with a moderate number of purposeful details. Friendly through proportion and curvature, never decorative cuteness.\n'
    'Composition: one fully visible isolated object, orthographic front three-quarter view, generous margins, light neutral studio background, soft studio lighting. No turntable, shared diorama slab, text, labels, logos, watermark, people, hearts, clouds, smileys, faces or sharp decorative spikes. Keep thick functional details readable and geometrically plausible.\n')
for name in state['batches'][number-1]['sets']:
    model_dir=ROOT/'Blender'/name; ref_dir=ROOT/'REF'/name
    assert not model_dir.exists() and not ref_dir.exists(),name+' already exists'
    model_dir.mkdir(parents=True); ref_dir.mkdir(parents=True)
    for folder in (model_dir,ref_dir):
        (folder/'.gitattributes').write_text('** -text\n',encoding='utf-8',newline='\n')
    (model_dir/'.gitignore').write_text('__pycache__/\n*.pyc\n*.blend[0-9]\n*.zip\n',encoding='utf-8',newline='\n')
    task=f'# {name}: {state["sets"][name]["theme"]}\n\nRead ../SET_WORKER_BRIEF.md and ../SET_BATCH_PLAN.md. Own only this set directory. Main supplies four sequential image references, mirrored into local REF/. Review is deferred by user instruction.\n\n'
    for asset in state['sets'][name]['assets']:
        slug=asset['slug']
        prompt=common+'Subject: '+subjects[slug]+'\nColor palette: '+palettes[name]+'.\nMaterials: clean simple PBR painted metal, rubber, muted glazing and appropriate masonry/roof surfaces, restrained seams and material variation.\n'
        (ref_dir/(slug+'.prompt.txt')).write_text(prompt,encoding='utf-8',newline='\n')
        task+=f'- `{slug}`: {asset["label"]}\n'
    (model_dir/'TASK.md').write_text(task,encoding='utf-8',newline='\n')
print(f'Prepared batch {number}: 12 prompts and three task roots. Images not generated by this script.')
